<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Book; use App\Models\Order; use App\Models\User; use Illuminate\Http\Request;
class AdminDashboardController extends Controller { public function __invoke(Request $r) { $d=$r->validate(['from'=>['nullable','date'],'to'=>['nullable','date']]); $q=Order::query(); if($d['from']??null)$q->whereDate('created_at','>=',$d['from']); if($d['to']??null)$q->whereDate('created_at','<=',$d['to']); $orders=(clone $q); return response()->json(['data'=>['kpi'=>['orders'=>$orders->count(),'revenue'=>(clone $q)->whereIn('status',['paid','processing','packed','shipped','completed'])->sum('grand_total'),'customers'=>User::where('status','active')->whereDoesntHave('roles', fn($q) => $q->whereIn('name', ['super-admin', 'admin']))->count(),'pending_payment'=>(clone $q)->where('status','pending_payment')->count()],'recent_orders'=>(clone $q)->with('items')->latest()->take(10)->get(),'top_books'=>Book::orderByDesc('sold_count')->take(5)->get(['id','title','author','stock','sold_count']),'low_stock'=>Book::whereColumn('stock','<=','minimum_stock')->orderBy('stock')->take(10)->get(['id','title','sku','stock','minimum_stock'])]]); } }
